const PRICE = { in: 0.001, out: 0.002 };
function meter(model, inTokens, outTokens) {
  const cost = inTokens * PRICE.in + outTokens * PRICE.out;
  return { model, inTokens, outTokens, cost: cost.toFixed(6) };
}
const r1 = meter("gpt-x", 1200, 350);
const r2 = meter("gpt-x", 1200, 800);
console.log(JSON.stringify(r1));
console.log(JSON.stringify(r2));
console.log("两次总花费:", (parseFloat(r1.cost) + parseFloat(r2.cost)).toFixed(6));
